-- rtl/matvec_core.vhd -- subsystem A datapath core, ROWS_IF rows wide.
--
-- Implements the numeric contract of
--   docs/superpowers/specs/2026-08-20-int4-streaming-matvec-design.md  7.4
-- and is validated STAGE BY STAGE against ref/matvec_int4.c via
-- sim/matvec_trace.txt (see sim/tb_matvec_core.vhd).
--
-- The five arithmetic primitives come from work.mv4i_arith_pkg, which is
-- GENERATED by tools/gen_arith.py from the same description that emits the C
-- reference's mv4i_arith.h and the golden vectors both are checked against.
-- They are deliberately not hand-written here: every defect found in this
-- contract so far has been in exactly those functions.
--
-- Per spec 7.1 this is the CORE only.  Weights and scales arrive as valid/ready
-- STREAMS (weight_streamer sits above and is device-specific: DDR4 on the
-- AXU3EG, HBM on the FK33); activations are read from act_mem_striped, which is
-- addressed and has 1-cycle read latency.  The core itself is device-independent.
--
-- DATAFLOW.  One weight word per cycle carries ROWS_IF rows' worth of one scale
-- block, in the packer's tile-major order (spec 6.5): for tile t, for block b,
-- lane rr holds row t*ROWS_IF + rr.  So all ROWS_IF rows of a tile march through
-- the blocks together and accumulate in parallel, and the word order the packer
-- emits is exactly the order this core consumes.
--
-- The compute path is a NON-STALLING pipeline: it shifts every cycle carrying a
-- valid bit, so bubbles cost nothing and there is no backpressure logic inside
-- the datapath at all.  Backpressure exists only at the accept point.
-- Stage map, with LVL = log2(BLK):
--
--   s0            accept: register word / scales / activations / tag
--   s1            BLK x ROWS_IF products             (DSP48E2)
--   s2 .. s1+LVL  pipelined adder tree, spec 7.3  -> partial, s28
--   s2+LVL        scale multiply                     (DSP48E2, its OWN stage)
--   s3+LVL        floor_shr 15                    -> contrib, s29
--   s4+LVL        accumulate                      -> acc, s48
--
-- tr(l) pairs with tag tg(l+1); the offsets P_PART/P_CONTRIB/P_ACC below name
-- the stages so that alignment is stated once rather than open-coded.
--
-- Synthesizable: no `real`, no TEXTIO.  Note the datapath rules of 7.8/8: data
-- never travels through a VHDL `integer` (only exponents, descriptor fields and
-- loop counters do), and the scale multiply occupies its own pipeline stage so
-- it never shares one with the product multiplies -- the hazard that broke
-- residual, swiglu and bfp_pack on silicon in v1.0.

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.mv4i_arith_pkg.all;
use work.util_pkg.all;

entity matvec_core is
  generic(
    BLK         : positive := 32;     -- weights per scale block, spec 6.1
    ROWS_IF     : positive := 4;      -- rows in flight, spec 7.2 / 14.4
    MAXCOLS     : positive := 17408;  -- spec 14.1, 27B FFN
    MAXROWS_BFP : positive := 17408
  );
  port(
    clk, rst  : in  std_logic;
    start     : in  std_logic;

    -- descriptor
    n_rows    : in  integer;
    n_cols    : in  integer;                        -- TRUE K, spec 6.3
    out_shift : in  integer;                        -- 0..40, spec 7.4
    w_exp     : in  integer;
    x_exp     : in  integer;
    out_mode  : in  std_logic_vector(1 downto 0);   -- 00 BFP, 01 raw, 10 partial

    -- codebook, 16 x int8, runtime-loadable (spec 6.1).  Illegal outside idle.
    cb_we     : in  std_logic;
    cb_addr   : in  std_logic_vector(3 downto 0);
    cb_data   : in  std_logic_vector(7 downto 0);

    -- weight stream: one tile-block word, ROWS_IF lanes of BLK nibbles
    w_valid   : in  std_logic;
    w_data    : in  std_logic_vector(ROWS_IF*BLK*4-1 downto 0);
    w_ready   : out std_logic;
    -- scale stream: ROWS_IF uint15 in 16-bit fields, MSB must be 0
    s_valid   : in  std_logic;
    s_data    : in  std_logic_vector(ROWS_IF*16-1 downto 0);
    s_ready   : out std_logic;
    -- activation read, by BLK index; 1-cycle latency (spec 7.8)
    x_rbaddr  : out std_logic_vector(15 downto 0);
    x_rdata   : in  std_logic_vector(BLK*16-1 downto 0);

    -- Result, ROWS_IF rows per beat, y_addr = BASE row of the tile.
    -- 64 bits per row because PARTIAL mode carries the UNROUNDED s48 (14.2);
    -- BFP carries an int16 mantissa and raw an int32, both sign-extended.
    y_we      : out std_logic;
    y_addr    : out std_logic_vector(15 downto 0);
    y_data    : out std_logic_vector(ROWS_IF*64-1 downto 0);
    y_mask    : out std_logic_vector(ROWS_IF-1 downto 0);  -- 0 = pad row
    y_exp     : out integer;
    done      : out std_logic;                      -- one-cycle pulse
    err       : out std_logic;
    sat_event : out std_logic;                      -- sticky, spec 14.2

    -- STAGE TAPS.  One bus per stage rather than a shared one: stages retire
    -- concurrently in a pipeline, so a shared bus would drop taps.  Each carries
    -- ROWS_IF lanes of 64 bits.  Pruned by synthesis when left unconnected.
    tp_v, tc_v, ta_v, tm_v : out std_logic;
    tp_r, tc_r, ta_r, tm_r : out integer;           -- BASE row of the tile
    tp_b, tc_b             : out integer;
    tp_val, tc_val, ta_val, tm_val : out std_logic_vector(ROWS_IF*64-1 downto 0);
    tap_ns                 : out integer
  );
end entity;

architecture rtl of matvec_core is
  constant LVL   : natural  := clog2(BLK);          -- 5 at BLK = 32
  constant PIPE  : natural  := LVL + 5;             -- tag stages s0 .. s4+LVL
  constant P_PART    : natural := LVL + 1;          -- tg index of tr(LVL)
  constant P_SPROD   : natural := LVL + 2;
  constant P_CONTRIB : natural := LVL + 3;
  constant TILES : positive := (MAXROWS_BFP + ROWS_IF - 1) / ROWS_IF;

  type cb_t is array(0 to 15) of signed(7 downto 0);
  signal cb : cb_t := (others => (others => '0'));

  -- ybuf holds a whole tile per word, so all ROWS_IF rows are written together
  -- at row-end and read together at emit.  FLAT, not an array of arrays: a
  -- nested type does not infer BRAM (Vivado [Synth 8-11357] "RAM from
  -- Record/Structs") and builds registers instead -- 557,056 of them at
  -- MAXROWS_BFP=17408, against 141K on the ZU3EG.  The read is REGISTERED for
  -- the same reason, which is why emit is two stages below.
  type ybuf_t is array(0 to TILES-1) of std_logic_vector(ROWS_IF*32-1 downto 0);
  signal ybuf   : ybuf_t;
  attribute ram_style : string;
  attribute ram_style of ybuf : signal is "block";
  signal ybuf_q : std_logic_vector(ROWS_IF*32-1 downto 0) := (others => '0');

  type tag_t is record
    v     : std_logic;
    tile  : integer;
    blk   : integer;
    first : std_logic;   -- first block of its tile
    last  : std_logic;   -- last block of its tile
  end record;
  constant TAG0 : tag_t := ('0', 0, 0, '0', '0');
  type tag_arr is array(natural range <>) of tag_t;
  signal tg : tag_arr(0 to PIPE-1) := (others => TAG0);

  type node_arr is array(0 to ROWS_IF*BLK-1) of signed(27 downto 0);
  type lvl_arr  is array(0 to LVL) of node_arr;
  -- ADDER-TREE RECLAIM (A section 15.4a).  The array measures 46.5 DSP per row
  -- while containing only 33 multiplies: the balance is `(PCIN+A:B)` nodes,
  -- adder-tree levels sitting in DSP ALUs that the design does not need a DSP
  -- for.  Levels >= 2 are pushed into LUT fabric here.
  --
  -- The split into two signals is REQUIRED, and is the first of the two traps
  -- section 15.4a names.  Levels 0..LVL previously shared one signal `tr`, so a
  -- blanket `use_dsp = "no"` on it would have stripped the level-0 MULTIPLIERS
  -- as well as the adders -- the opposite of the intent.
  --
  -- The second trap is why level 1 stays on `tr`: it costs zero DSPs today
  -- because it fuses onto the multiplier as `(PCIN+(A2*B)')` and rides the DSP
  -- cascade for free.  Forcing it into fabric spends LUTs to save nothing.
  signal tr  : lvl_arr := (others => (others => (others => '0')));   -- levels 0..1
  signal trn : lvl_arr := (others => (others => (others => '0')));   -- levels 2..LVL
  attribute use_dsp : string;
  attribute use_dsp of trn : signal is "no";

  type sc_arr  is array(0 to ROWS_IF-1) of unsigned(15 downto 0);
  type scp_t   is array(0 to PIPE-1) of sc_arr;
  type sp_arr  is array(0 to ROWS_IF-1) of signed(44 downto 0);
  type ct_arr  is array(0 to ROWS_IF-1) of signed(28 downto 0);
  type acc_arr is array(0 to ROWS_IF-1) of signed(47 downto 0);

  signal scp     : scp_t   := (others => (others => (others => '0')));
  signal sprod   : sp_arr  := (others => (others => '0'));
  signal contrib : ct_arr  := (others => (others => '0'));
  signal acc     : acc_arr := (others => (others => '0'));

  signal w_r : std_logic_vector(ROWS_IF*BLK*4-1 downto 0) := (others => '0');
  signal x_r : std_logic_vector(BLK*16-1 downto 0)        := (others => '0');

  type st_t is (S_IDLE, S_RUN, S_DRAIN, S_SCAN, S_EMIT, S_DONE);
  signal st : st_t := S_IDLE;

  signal nb_r, tiles_r, lastvalid : integer := 0;
  signal t_iss, b_iss  : integer := 0;              -- next word to accept
  signal amax   : unsigned(35 downto 0) := (others => '0');
  -- NS, THE BFP OUTPUT SHIFT, AND WHY IT IS DECLARED AND REPLICATED LIKE THIS.
  --
  -- ns is one small control value that steers the VARIABLE shift of every one
  -- of the ROWS_IF emit lanes (SITE 4, in S_EMIT below).  At the FK33's
  -- ROWS_IF = 58 that is a single register driving 58 lanes of 32-bit barrel
  -- shifter, spread across whatever the placer does with 1,914 DSPs and 135k
  -- LUTs.  First place-and-route at the card's real 0.717 V put the resulting
  -- net at the top of the design:
  --
  --   ns_r_reg[1]_rep__7/C -> em_shv_reg[54][17]/D
  --   slack -2.495   logic 2.543   NET 3.045   (54.5% route)   172.6 MHz
  --
  -- `_rep__7` is Vivado having already replicated it seven times by itself and
  -- still not making timing.  Two things are wrong and they are independent:
  --
  -- (1) WIDTH.  ns was declared plain `integer`, so a value whose range is 0
  --     to 22 was broadcast as 32 bits.  msb_pos_u of a 36-bit amax is 0..36
  --     and ns = max(0, that - 14), so 0..22 is the true range and six bits
  --     hold it with room to spare.  `natural range 0 to 63` is what the
  --     synthesiser needs to see; it cannot infer the range from the two
  --     assignments in S_SCAN.  This cuts the broadcast by 5.3x before any
  --     replication, and it is the cheaper of the two fixes by a distance.
  --
  -- (2) FANOUT.  One driver, ROWS_IF sinks, placed apart.  The remedy is the
  --     one measured on gdn_silu's shift control, where the same shape cost
  --     2.812 ns of net delay and per-lane registered copies took it to
  --     0.530 ns: give each lane its OWN register holding the same value, so
  --     the placer can put the copy next to the lane it feeds instead of
  --     routing one net to all of them.  DONT_TOUCH is what makes that stick:
  --     the copies are functionally identical and equivalent-register-removal
  --     merges them straight back into one net otherwise.
  --
  -- THE COST IS ZERO CYCLES, and that is a property of the state machine, not
  -- an accident.  ns_r is written in S_SCAN, S_SCAN unconditionally enters
  -- S_EMIT, and S_EMIT also clears rd_v so its FIRST cycle never writes
  -- em_shv.  So the first read of the shift amount is two cycles after ns_r is
  -- written, and a replica that tracks ns_r with one cycle of delay is already
  -- correct by then.  The margin is exactly one cycle -- it is sufficient, not
  -- generous, and anything that makes S_EMIT start emitting a cycle earlier
  -- eats it.  tb_matvec_core checks the emitted y against ref/matvec_int4.c
  -- bit for bit, so that boundary is covered by the existing suite.
  --
  -- tap_ns and y_exp deliberately keep reading the MASTER ns_r, not a replica.
  -- Both are single-sink and neither is on this path, and a control value that
  -- is one cycle late in one consumer and not another is exactly the silent
  -- defect this file has been bitten by before.  ns_r is constant for the
  -- whole of S_EMIT, so master and replica agree everywhere either is read.
  subtype ns_t is natural range 0 to 63;
  signal ns_r   : ns_t := 0;
  type   ns_arr is array(0 to ROWS_IF-1) of ns_t;
  signal ns_rep : ns_arr := (others => 0);
  -- OUT_SHIFT GETS THE SAME TREATMENT, AND FOR A THIRD REASON AS WELL.
  --
  -- SITE 2/3's row-end shift at `re2_shv(rr) <= round_shift(re1_acc(rr), ...)`
  -- is the identical shape to SITE 4's: one small control value steering a
  -- VARIABLE shift in all ROWS_IF lanes.  It is worse on two counts.  The
  -- datapath is 48 bits rather than 32, so each lane is a bigger shifter and a
  -- 49-bit one-hot bias decoder.  And the control value is an input PORT
  -- declared `integer`, so the 32-bit broadcast starts wherever the wrapper's
  -- register was placed, outside this module entirely.
  --
  -- It was not the reported critical path -- ns was -- so this is a prediction,
  -- not a measurement: once ns is fixed, this is the same defect waiting in the
  -- same place.  The file header already records that round_shift by a variable
  -- out_shift WAS the critical path once, at -6.354 ns, which is what forced
  -- row end to be split into stages in the first place.
  --
  -- The third reason is not about timing at all.  out_shift was read LIVE, in
  -- every lane, at every tile's row end, across an operation that runs for
  -- thousands of cycles.  That is an unlatched input read across a long
  -- operation, which is defect class 1 in
  -- docs/debugging/2026-08-27_B-interface-audit.md, and it means a caller that
  -- moved out_shift mid-operation would get DIFFERENT tiles rounded by
  -- DIFFERENT shifts with nothing detecting it.  os_r latches it once, in the
  -- arm of the S_IDLE check that has just proved 0 <= out_shift <= 40, so the
  -- narrow subtype cannot be violated by a caller the check is about to reject.
  -- y_exp reads os_r for the same reason: one operation, one shift, everywhere.
  subtype os_t is natural range 0 to 63;
  signal os_r   : os_t := 0;
  type   os_arr is array(0 to ROWS_IF-1) of os_t;
  signal os_rep : os_arr := (others => 0);
  attribute dont_touch : string;
  attribute dont_touch of ns_rep : signal is "true";
  attribute dont_touch of os_rep : signal is "true";
  signal sat_r, err_r : std_logic := '0';

  -- ROW-END PIPELINE.  Row end runs once per TILE, not once per block, so
  -- latency here is nearly free while the combinational chain it replaces was
  -- the critical path: acc+contrib -> round_shift by a VARIABLE out_shift (a
  -- 48-bit barrel shifter) -> sat32 -> abs -> a ROWS_IF-way max fold -> amax,
  -- all in one cycle.  Measured at -6.354 ns against a 5 ns period, i.e. 88 MHz
  -- against the 200 MHz that 14.4 pins.
  type sh_arr  is array(0 to ROWS_IF-1) of signed(47 downto 0);
  type mag_arr is array(0 to ROWS_IF-1) of unsigned(35 downto 0);
  signal re1_v, re2_v, re3_v : std_logic := '0';
  signal re1_t, re2_t, re3_t : integer := 0;
  signal re1_acc, re2_acc    : acc_arr := (others => (others => '0'));
  signal re2_shv             : sh_arr  := (others => (others => '0'));
  signal re3_mag             : mag_arr := (others => (others => '0'));
  signal re3_ok              : std_logic_vector(ROWS_IF-1 downto 0) := (others => '0');
  -- The amax fold is a TREE not a chain, and the tree is now PIPELINED, one
  -- register stage per level.
  --
  -- As a chain it was the critical path after row end was split (re3_mag ->
  -- amax, -0.159 ns).  Making it a tree fixed that at ROWS_IF=4, but an OOC
  -- sweep on xcku5p at 300 MHz found the whole tree in ONE stage is the
  -- critical path at EVERY ROWS_IF, and worsens as ROWS_IF grows:
  --
  --   ROWS_IF     4      8     16     24     32
  --   Fmax      266    287    222    168    180  MHz
  --
  --   Source: re3_mag_reg[5][0]/C  Destination: re4_max_reg[0]/D
  --   Logic Levels: 28 (CARRY8=15 ...)   @ ROWS_IF=24
  --
  -- Depth is log2(ROWS_IF) 36-bit compares, and routing was 63-68% of the path
  -- because the fan-in spreads further across the die as ROWS_IF grows -- which
  -- registers help with directly, not just the logic depth.  At the FK33's
  -- ROWS_IF this is the difference between the design closing and not.
  --
  -- LATENCY IS FREE HERE, but only because of what consumes amax: it is a
  -- running maximum over the WHOLE matrix, read once in S_SCAN after the
  -- pipeline has drained.  Nothing downstream sees the extra cycles.  That does
  -- mean `inflight` MUST cover these stages -- see the note there.
  function lvl_of(r : positive) return positive is
    variable c : natural := clog2(r);
  begin
    if c = 0 then return 1; else return c; end if;   -- ROWS_IF=1 still needs one
  end function;
  constant LVLR   : positive := lvl_of(ROWS_IF);
  constant MAXPOW : positive := 2 ** LVLR;
  constant HALF   : positive := MAXPOW / 2;
  type wide_mag is array(0 to MAXPOW-1) of unsigned(35 downto 0);
  -- FLAT, not an array of arrays: stage s owns [s*HALF .. s*HALF+HALF-1] and
  -- only the first MAXPOW/2**(s+1) entries of it are ever written or read, so
  -- synthesis trims the rest.  Flat deliberately -- nested arrays are what
  -- blocked RAM inference elsewhere in this file, and there is no reason to
  -- re-learn that lesson for a register file.
  type fold_arr is array(0 to LVLR*HALF-1) of unsigned(35 downto 0);
  signal fold   : fold_arr := (others => (others => '0'));
  signal fold_v : std_logic_vector(LVLR-1 downto 0) := (others => '0');
  -- emit is a 2-stage read: rd_t is presented, and one cycle later the data
  -- appears in ybuf_q tagged by rd_td.
  signal rd_t, rd_td : integer := 0;
  signal rd_v        : std_logic := '0';
  -- and one more stage after the BRAM read: SITE 4's round_shift is a variable
  -- shift by ns, which became the critical path once row end was split
  -- (ybuf BRAM -> round_shift -> sat16 -> y_data, WNS -0.596 ns).
  signal em_v        : std_logic := '0';
  signal em_t        : integer := 0;
  type   em_arr is array(0 to ROWS_IF-1) of signed(31 downto 0);
  signal em_shv      : em_arr := (others => (others => '0'));

  -- Activation prefetch.  The block sequence is deterministic (0..nb-1 repeated
  -- per tile), so a 2-deep queue run ahead of the accept point keeps the
  -- pipeline fed at full rate across the memory's 1-cycle read latency.
  type xq_t is array(0 to 1) of std_logic_vector(BLK*16-1 downto 0);
  signal xq           : xq_t := (others => (others => '0'));
  signal xq_wr, xq_rd : integer range 0 to 1 := 0;
  signal xq_cnt       : integer range 0 to 2 := 0;
  signal b_pf         : integer := 0;
  signal pf_out       : std_logic := '0';

  signal accept  : std_logic;
  signal inflight: std_logic;
begin

  -- The adder-tree reclaim routing assumes at least one fabric level
  -- exists (BLK >= 4).  BLK = 32 in every configuration used, giving
  -- LVL = 5, but BLK is a generic, so check rather than assume.
  assert LVL >= 2
    report "matvec_core: adder-tree reclaim needs LVL >= 2, i.e. BLK >= 4"
    severity failure;

  accept <= '1' when st = S_RUN and w_valid = '1' and s_valid = '1'
                     and xq_cnt > 0 else '0';
  w_ready  <= accept;
  s_ready  <= accept;
  x_rbaddr <= std_logic_vector(to_unsigned(b_pf, 16));

  -- any beat still in the compute pipeline
  -- The fold stages MUST be counted here.  S_DRAIN leaves on inflight='0' and
  -- S_SCAN reads amax the cycle after; with an unpipelined fold that left
  -- exactly one cycle of margin, which the pipeline would consume, and the last
  -- rows' magnitudes would never reach amax.  The result would be an ns too
  -- small for the true maximum -- so a silently wrong exponent on some shapes,
  -- not a crash.  Note the previous version listed re4_v in the sensitivity
  -- list but never used it in the expression; that was harmless only because
  -- the one-cycle margin happened to cover it.
  process(tg, re1_v, re2_v, re3_v, fold_v)
    variable o : std_logic;
  begin
    o := re1_v or re2_v or re3_v;
    for i in 0 to LVLR-1 loop o := o or fold_v(i); end loop;
    for i in 0 to PIPE-1 loop o := o or tg(i).v; end loop;
    inflight <= o;
  end process;

  process(clk)
    variable idx   : integer;
    variable xw    : signed(15 downto 0);
    variable k     : integer;
    variable nxt   : tag_arr(0 to PIPE-1);
    variable nsc   : scp_t;
    variable occ   : integer range -1 to 3;
    variable an    : signed(47 downto 0);
    variable a32   : signed(31 downto 0);
    variable shv   : signed(47 downto 0);
    variable mag, mxv : unsigned(35 downto 0);
    variable rbase : integer;
    variable ymn   : signed(15 downto 0);
    variable ynew  : std_logic_vector(ROWS_IF*32-1 downto 0);
    variable wm    : wide_mag;
  begin
    if rising_edge(clk) then
      y_we <= '0'; done <= '0'; re1_v <= '0';
      tp_v <= '0'; tc_v <= '0'; ta_v <= '0'; tm_v <= '0';

      if rst = '1' then
        st <= S_IDLE; sat_r <= '0'; err_r <= '0';
        tg <= (others => TAG0);
        fold_v <= (others => '0');
        xq_cnt <= 0; xq_wr <= 0; xq_rd <= 0; pf_out <= '0'; b_pf <= 0;

      elsif cb_we = '1' and st = S_IDLE then
        cb(to_integer(unsigned(cb_addr))) <= signed(cb_data);

      else
        ----------------------------------------------------------------
        -- activation prefetch queue
        ----------------------------------------------------------------
        occ := xq_cnt;
        if pf_out = '1' then                     -- a read lands this edge
          xq(xq_wr) <= x_rdata;
          xq_wr     <= (xq_wr + 1) mod 2;
          occ       := occ + 1;
        end if;
        if accept = '1' then
          x_r   <= xq(xq_rd);
          xq_rd <= (xq_rd + 1) mod 2;
          occ   := occ - 1;
        end if;
        xq_cnt <= occ;
        if st = S_RUN and occ < 2 then
          pf_out <= '1';
          if b_pf = nb_r - 1 then b_pf <= 0; else b_pf <= b_pf + 1; end if;
        else
          pf_out <= '0';
        end if;

        ----------------------------------------------------------------
        -- tag + scale shift.  Always advances; `v` gates every effect.
        ----------------------------------------------------------------
        nxt := tg;  nsc := scp;
        for i in PIPE-1 downto 1 loop
          nxt(i) := tg(i-1);
          nsc(i) := scp(i-1);
        end loop;
        nxt(0) := TAG0;
        if accept = '1' then
          w_r <= w_data;
          for rr in 0 to ROWS_IF-1 loop
            nsc(0)(rr) := unsigned(s_data(rr*16+15 downto rr*16));
          end loop;
          nxt(0).v    := '1';
          nxt(0).tile := t_iss;
          nxt(0).blk  := b_iss;
          if b_iss = 0        then nxt(0).first := '1';
          else                     nxt(0).first := '0'; end if;
          if b_iss = nb_r - 1 then nxt(0).last  := '1';
          else                     nxt(0).last  := '0'; end if;
          if b_iss = nb_r - 1 then
            b_iss <= 0;
            if t_iss = tiles_r - 1 then st <= S_DRAIN;
            else t_iss <= t_iss + 1; end if;
          else
            b_iss <= b_iss + 1;
          end if;
        end if;
        tg <= nxt;  scp <= nsc;

        ----------------------------------------------------------------
        -- s1: products.  COLUMN MASK (6.2) is required because the IQ4_NL
        -- codebook has no zero entry -- index 0 decodes to -127, so padding
        -- must be masked, never zero-filled.
        ----------------------------------------------------------------
        if tg(0).v = '1' then
        for rr in 0 to ROWS_IF-1 loop
          for j in 0 to BLK-1 loop
            idx := to_integer(unsigned(
                     w_r((rr*BLK + j)*4 + 3 downto (rr*BLK + j)*4)));
            xw  := signed(x_r(j*16+15 downto j*16));
            k   := tg(0).blk * BLK + j;
            if k < n_cols then
              tr(0)(rr*BLK + j) <= resize(cb(idx) * xw, 28);
            else
              tr(0)(rr*BLK + j) <= (others => '0');
            end if;
          end loop;
        end loop;
        end if;

        ----------------------------------------------------------------
        -- s2..s1+LVL: pipelined adder tree (spec 7.3, NOT a DSP cascade)
        ----------------------------------------------------------------
        for l in 1 to LVL loop
          if tg(l).v = '1' then
          for rr in 0 to ROWS_IF-1 loop
            for i in 0 to (BLK / (2**l)) - 1 loop
              if l = 1 then
                -- stays in the DSP: fuses onto the multiply via PCIN
                tr(l)(rr*BLK + i)  <= tr(l-1)(rr*BLK + 2*i)
                                    + tr(l-1)(rr*BLK + 2*i + 1);
              elsif l = 2 then
                -- first fabric level, still sourced from the DSP-resident tr(1)
                trn(l)(rr*BLK + i) <= tr(l-1)(rr*BLK + 2*i)
                                    + tr(l-1)(rr*BLK + 2*i + 1);
              else
                trn(l)(rr*BLK + i) <= trn(l-1)(rr*BLK + 2*i)
                                    + trn(l-1)(rr*BLK + 2*i + 1);
              end if;
            end loop;
          end loop;
          end if;
        end loop;

        ----------------------------------------------------------------
        -- s2+LVL: scale multiply, ALONE in its stage
        ----------------------------------------------------------------
        if tg(P_PART).v = '1' then
          for rr in 0 to ROWS_IF-1 loop
            sprod(rr) <= trn(LVL)(rr*BLK) * signed('0' & scp(P_PART)(rr));
          end loop;
        end if;
        if tg(P_PART).v = '1' then
          tp_v <= '1'; tp_r <= tg(P_PART).tile * ROWS_IF; tp_b <= tg(P_PART).blk;
          for rr in 0 to ROWS_IF-1 loop
            tp_val(rr*64+63 downto rr*64)
              <= std_logic_vector(resize(trn(LVL)(rr*BLK), 64));
          end loop;
        end if;

        ----------------------------------------------------------------
        -- s3+LVL: SITE 1, floor(partial * scale / 2^15)
        ----------------------------------------------------------------
        if tg(P_SPROD).v = '1' then
          for rr in 0 to ROWS_IF-1 loop
            contrib(rr) <= resize(floor_shr(sprod(rr), 15), 29);
          end loop;
        end if;

        ----------------------------------------------------------------
        -- s4+LVL: accumulate, and row-end on the tile's last block
        ----------------------------------------------------------------
        if tg(P_CONTRIB).v = '1' then
          tc_v <= '1'; tc_r <= tg(P_CONTRIB).tile * ROWS_IF;
          tc_b <= tg(P_CONTRIB).blk;
          rbase := tg(P_CONTRIB).tile * ROWS_IF;

          for rr in 0 to ROWS_IF-1 loop
            tc_val(rr*64+63 downto rr*64)
              <= std_logic_vector(resize(contrib(rr), 64));
            -- `first` restarts the sum in place, so back-to-back tiles need
            -- no bubble and acc never has to be cleared out of band.
            if tg(P_CONTRIB).first = '1' then an := resize(contrib(rr), 48);
            else                              an := acc(rr) + resize(contrib(rr), 48);
            end if;
            acc(rr) <= an;
            if tg(P_CONTRIB).last = '1' then
              ta_val(rr*64+63 downto rr*64) <= std_logic_vector(resize(an, 64));
              re1_acc(rr) <= an;          -- hand off to the row-end pipeline
            end if;
          end loop;

          if tg(P_CONTRIB).last = '1' then
            ta_v <= '1'; ta_r <= rbase;
            re1_v <= '1'; re1_t <= tg(P_CONTRIB).tile;
          end if;
        end if;

        ----------------------------------------------------------------
        -- row end, stage 2: SITE 2/3, the variable shift, alone
        ----------------------------------------------------------------
        re2_v <= re1_v; re2_t <= re1_t;
        if re1_v = '1' then
          for rr in 0 to ROWS_IF-1 loop
            -- os_rep(rr), not out_shift: latched, narrowed, per-lane.  To
            -- attribute, put out_shift back HERE and nowhere else.
            re2_shv(rr) <= round_shift(re1_acc(rr), os_rep(rr));
            re2_acc(rr) <= re1_acc(rr);        -- PARTIAL emits this, unrounded
          end loop;
        end if;

        ----------------------------------------------------------------
        -- row end, stage 3: saturate, store, emit
        ----------------------------------------------------------------
        re3_v <= re2_v; re3_t <= re2_t;
        if re2_v = '1' then
          rbase := re2_t * ROWS_IF;
          for rr in 0 to ROWS_IF-1 loop
            a32 := sat32(re2_shv(rr));
            -- 14.2: partial mode emits the UNROUNDED s48 and never applies
            -- sat32, so a sat here is an artefact of a value this mode
            -- discards.  Reporting it would make E reject good partials in
            -- exactly the cancellation cases where a K-slice legitimately
            -- exceeds the full-K result.  Sticky only where sat32 is real.
            if out_mode /= "10" and re2_shv(rr) /= resize(a32, 48) then
              sat_r <= '1';
            end if;
            ynew(rr*32+31 downto rr*32) := std_logic_vector(a32);
            re3_mag(rr) <= unsigned(abs(resize(a32, 36)));
            if out_mode = "10" then
              -- 14.2: PARTIAL emits the accumulator UNROUNDED.  round_shift is
              -- not additive, so rounding per shard could never reproduce the
              -- full-K result.  No round, no saturation.
              y_data(rr*64+63 downto rr*64)
                <= std_logic_vector(resize(re2_acc(rr), 64));
            else
              y_data(rr*64+63 downto rr*64) <= std_logic_vector(resize(a32, 64));
            end if;
            if rbase + rr < n_rows then
              y_mask(rr) <= '1'; re3_ok(rr) <= '1';
            else
              y_mask(rr) <= '0'; re3_ok(rr) <= '0';
            end if;
          end loop;
          -- written as ONE full-width word: lane-by-lane slice assignment looks
          -- like a partial write and pushes Vivado into byte-wide write enables
          if out_mode /= "10" then ybuf(re2_t) <= ynew; end if;
          y_addr <= std_logic_vector(to_unsigned(rbase, 16));
          if out_mode /= "00" then y_we <= '1'; end if;
        end if;

        ----------------------------------------------------------------
        -- row end, stage 4: the amax fold, alone
        ----------------------------------------------------------------
        -- level 1 of the tree, fed from the masked magnitudes
        fold_v(0) <= re3_v;
        if re3_v = '1' then
          -- SCAN DOMAIN is r < n_rows ONLY: a pad row folded into amax would
          -- inflate ns and crush every real mantissa.  Masked to zero here, so
          -- the tree below needs no per-node validity.
          for rr in 0 to ROWS_IF-1 loop
            if re3_ok(rr) = '1' then wm(rr) := re3_mag(rr);
            else                     wm(rr) := (others => '0'); end if;
          end loop;
          for rr in ROWS_IF to MAXPOW-1 loop     -- pad to a power of two
            wm(rr) := (others => '0');
          end loop;
          for i in 0 to HALF-1 loop
            if wm(2*i+1) > wm(2*i) then fold(i) <= wm(2*i+1);
            else                        fold(i) <= wm(2*i); end if;
          end loop;
        end if;

        -- levels 2..LVLR, one register stage each.  Stage s reads stage s-1's
        -- region and writes its own, halving the live count each time.
        for sg in 1 to LVLR-1 loop
          fold_v(sg) <= fold_v(sg-1);
          if fold_v(sg-1) = '1' then
            for i in 0 to (MAXPOW / (2**(sg+1))) - 1 loop
              if fold((sg-1)*HALF + 2*i+1) > fold((sg-1)*HALF + 2*i) then
                fold(sg*HALF + i) <= fold((sg-1)*HALF + 2*i+1);
              else
                fold(sg*HALF + i) <= fold((sg-1)*HALF + 2*i);
              end if;
            end loop;
          end if;
        end loop;

        ----------------------------------------------------------------
        -- row end, stage 5: accumulate the running maximum
        ----------------------------------------------------------------
        -- the tree's last stage holds exactly one live entry, at sg=LVLR-1
        if fold_v(LVLR-1) = '1' and fold((LVLR-1)*HALF) > amax then
          amax <= fold((LVLR-1)*HALF);
        end if;

        -- Registered ybuf read, issued UNCONDITIONALLY: gating it on the state
        -- would stop it inferring a BRAM read port.  rd_v is raised in the
        -- ISSUE branch below rather than registered from a separate flag,
        -- because this read and that branch both sample the same pre-edge rd_t
        -- -- deriving rd_v from a registered rd_go delays it one cycle further
        -- than the data and silently drops the first tile.
        ybuf_q <= ybuf(rd_t);

        -- Per-lane copies of the emit shift, updated UNCONDITIONALLY so they
        -- are always exactly ns_r delayed by one cycle -- see the declaration.
        -- No state test here on purpose: a gated replica would only track ns_r
        -- while the gate is true, which is the version of this that is wrong.
        for rr in 0 to ROWS_IF-1 loop
          ns_rep(rr) <= ns_r;
          os_rep(rr) <= os_r;
        end loop;

        ----------------------------------------------------------------
        -- control
        ----------------------------------------------------------------
        case st is
          when S_IDLE =>
            if start = '1' then                        -- spec 7.6 checks
              if n_rows <= 0 or n_cols <= 0 or n_cols > MAXCOLS
                 or out_shift < 0 or out_shift > 40
                 or (out_mode = "00" and n_rows > MAXROWS_BFP) then
                err_r <= '1'; st <= S_DONE;
              else
                nb_r      <= (n_cols + BLK - 1) / BLK;              -- 6.3 ceil
                tiles_r   <= (n_rows + ROWS_IF - 1) / ROWS_IF;
                lastvalid <= n_cols - ((n_cols - 1) / BLK) * BLK;
                t_iss <= 0; b_iss <= 0; b_pf <= 0;
                xq_cnt <= 0; xq_wr <= 0; xq_rd <= 0; pf_out <= '0';
                amax <= (others => '0');
                os_r      <= out_shift;      -- checked 0..40 immediately above
                sat_r <= '0'; err_r <= '0';
                st <= S_RUN;
              end if;
            end if;

          when S_RUN | S_DRAIN =>
            if st = S_DRAIN and inflight = '0' then
              if out_mode = "00" then st <= S_SCAN; else st <= S_DONE; end if;
            end if;

          when S_SCAN =>
            -- ns = max(0, msb_pos(amax) - 14); msb_pos(0) = 0 is NORMATIVE
            if msb_pos_u(amax) > 14 then ns_r <= msb_pos_u(amax) - 14;
            else                         ns_r <= 0; end if;
            rd_t <= 0; rd_v <= '0'; em_v <= '0';
            st <= S_EMIT;

          when S_EMIT =>
            tap_ns <= ns_r;
            if rd_t < tiles_r then
              rd_v <= '1'; rd_td <= rd_t; rd_t <= rd_t + 1;
            else
              rd_v <= '0';
            end if;

            -- emit stage 1: SITE 4's shift, alone
            em_v <= rd_v; em_t <= rd_td;
            if rd_v = '1' then
              for rr in 0 to ROWS_IF-1 loop
                -- ns_rep(rr), not ns_r: the per-lane replica.  To attribute
                -- the two fixes separately, put ns_r back HERE and nowhere
                -- else -- that measures the width narrowing on its own.
                em_shv(rr) <= resize(round_shift(
                                signed(ybuf_q(rr*32+31 downto rr*32)),
                                ns_rep(rr)), 32);
              end loop;
            end if;

            -- emit stage 2: saturate and drive the port
            if em_v = '1' then
              rbase := em_t * ROWS_IF;
              y_we   <= '1';
              y_addr <= std_logic_vector(to_unsigned(rbase, 16));
              tm_v <= '1'; tm_r <= rbase;
              for rr in 0 to ROWS_IF-1 loop
                ymn := sat16(em_shv(rr));
                y_data(rr*64+63 downto rr*64) <= std_logic_vector(resize(ymn, 64));
                tm_val(rr*64+63 downto rr*64) <= std_logic_vector(resize(ymn, 64));
                if rbase + rr < n_rows then y_mask(rr) <= '1';
                else                        y_mask(rr) <= '0'; end if;
              end loop;
              if em_t = tiles_r - 1 then st <= S_DONE; end if;
            end if;

          when S_DONE =>
            done <= '1';
            st   <= S_IDLE;
        end case;
      end if;
    end if;
  end process;

  -- y_exp: BFP subtracts ns (spec 7.4); PARTIAL carries NO out_shift term
  -- (spec 14.2), because its payload was never shifted.
  -- os_r, not out_shift: the shift the datapath ACTUALLY applied.  With a
  -- caller that holds out_shift for the operation, as the contract requires,
  -- these are the same value; with one that does not, this is the only version
  -- that cannot report an exponent for a rounding the payload never had.
  y_exp <= (w_exp + x_exp)                        when out_mode = "10" else
           (w_exp + x_exp - os_r - ns_r)          when out_mode = "00" else
           (w_exp + x_exp - os_r);

  err       <= err_r;
  sat_event <= sat_r;
end architecture;
